import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void tanh_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int64_t numel
) {
    int64_t index = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    int64_t stride = static_cast<int64_t>(blockDim.x) * gridDim.x;

    for (; index < numel; index += stride) {
        output[index] = tanhf(input[index]);
    }
}

torch::Tensor tanh_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");

    const c10::cuda::CUDAGuard device_guard(input.device());
    auto output = torch::empty_like(input);

    const int threads = 256;
    const int64_t numel = input.numel();
    const int blocks = static_cast<int>(
        std::min<int64_t>((numel + threads - 1) / threads, 65535)
    );

    if (numel > 0) {
        tanh_kernel<<<blocks, threads, 0, at::cuda::getDefaultCUDAStream()>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            numel
        );
    }

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
"""

_cpp_src = r"""
#include <torch/extension.h>

torch::Tensor tanh_cuda(torch::Tensor input);
"""

_tanh_extension = load_inline(
    name="custom_tanh_cuda",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["tanh_cuda"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _tanh_extension.tanh_cuda(x)

